mapper.select:
SELECT SETTING_KEY AS settingKey, SETTING_VALUE AS settingValue, DESCRIPTION AS description
  FROM APP_SETTING
 WHERE SETTING_KEY = #{settingKey}

mapper.update:
UPDATE APP_SETTING
   SET SETTING_VALUE = #{settingValue}, UPDATED_BY = #{updatedBy}, UPDATED_AT = #{now}
 WHERE SETTING_KEY = #{settingKey}
